p = 17
q = 19
e = 5


def Saisie():
    b = False
    while not b:
        ch = str(input('Donner une chaine :'))
        b = verif(ch)
    return ch


def verif(ch):
    ok = True
    i = -1
    while ok and i < len(ch) - 1:
        i += 1
        ok = "A" <= ch[i].upper() <= "Z"
    return ok


def Remplir(mot):
    for i in range(len(mot)):
        T[i] = ord(mot[i].upper()) - 64
    return len(mot)


def Crypter(T, n):
    for i in range(n):
        a = puissance(T[i], e) % (p * q)
        T[i] = a


def puissance(x, y):
    R = 1
    for i in range(y):
        R *= x
    return R


def Afficher(T, n):
    for i in range(n):
        print(T[i], end=' ')


